_MAX_FORMULA_LENGTH = 60
_WHITESPACE = " \t\n\r\f\v"
_ALLOWED_VARS = ("id", "n")


def _tokenize(formula: str) -> list[tuple[str, object]]:
    tokens: list[tuple[str, object]] = []
    i = 0
    length = len(formula)
    while i < length:
        ch = formula[i]
        if ch in _WHITESPACE:
            i += 1
        elif "0" <= ch <= "9":
            j = i
            while j < length and "0" <= formula[j] <= "9":
                j += 1
            tokens.append(("int", int(formula[i:j])))
            i = j
        elif ("a" <= ch <= "z") or ("A" <= ch <= "Z") or ch == "_":
            j = i
            while j < length and (formula[j].isalnum() or formula[j] == "_"):
                j += 1
            word = formula[i:j]
            if word not in _ALLOWED_VARS:
                raise ValueError("invalid formula")
            tokens.append(("var", word))
            i = j
        elif ch == "/":
            if i + 1 < length and formula[i + 1] == "/":
                tokens.append(("op", "//"))
                i += 2
            else:
                raise ValueError("invalid formula")
        elif ch in "+-*":
            tokens.append(("op", ch))
            i += 1
        elif ch == "(":
            tokens.append(("(", "("))
            i += 1
        elif ch == ")":
            tokens.append((")", ")"))
            i += 1
        else:
            raise ValueError("invalid formula")
    return tokens


class _Parser:
    def __init__(self, tokens: list[tuple[str, object]]) -> None:
        self._tokens = tokens
        self._pos = 0

    def parse(self):
        node = self._expression()
        if self._pos != len(self._tokens):
            raise ValueError("invalid formula")
        return node

    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _advance(self):
        token = self._tokens[self._pos]
        self._pos += 1
        return token

    def _expression(self):
        node = self._term()
        while True:
            token = self._peek()
            if token is not None and token[0] == "op" and token[1] in ("+", "-"):
                self._advance()
                node = ("bin", token[1], node, self._term())
            else:
                return node

    def _term(self):
        node = self._factor()
        while True:
            token = self._peek()
            if token is not None and token[0] == "op" and token[1] in ("*", "//"):
                self._advance()
                node = ("bin", token[1], node, self._factor())
            else:
                return node

    def _factor(self):
        token = self._peek()
        if token is not None and token[0] == "op" and token[1] == "-":
            self._advance()
            return ("neg", self._factor())
        return self._atom()

    def _atom(self):
        token = self._peek()
        if token is None:
            raise ValueError("invalid formula")
        if token[0] == "int":
            self._advance()
            return ("num", token[1])
        if token[0] == "var":
            self._advance()
            return ("var", token[1])
        if token[0] == "(":
            self._advance()
            node = self._expression()
            closing = self._peek()
            if closing is None or closing[0] != ")":
                raise ValueError("invalid formula")
            self._advance()
            return node
        raise ValueError("invalid formula")


